mapper.select:
SELECT COUNT(*) FROM rwd_grant_record
WHERE user_id = #{userId}
  AND prize_id = #{prizeId}
  AND status IN ('GRANTED', 'WON', 'CLAIMING', 'RETRY_PENDING')
  AND created_at >= #{from}

SELECT * FROM rwd_grant_record
WHERE grant_source = #{grantSource}
  AND source_id = #{sourceId}
  AND prize_id = #{prizeId}
LIMIT 1

mapper.update:
UPDATE rwd_grant_record
SET fulfillment_ref = #{fulfillmentRef}
WHERE id = #{id}
  AND fulfillment_ref IS NULL

mapper.select:
SELECT * FROM rwd_grant_record
WHERE status = 'RETRY_PENDING'
  AND next_retry_at <= #{now}
  AND (expire_at IS NULL OR expire_at > #{now})
ORDER BY next_retry_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE rwd_grant_record
SET status = 'EXPIRED',
    updated_at = #{now}
WHERE id = #{id}
  AND status IN ('WON', 'RETRY_PENDING', 'CLAIMING')
  AND expire_at IS NOT NULL
  AND expire_at <= #{now}

UPDATE rwd_grant_record
SET status = 'PERMANENT_FAILED',
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'RETRY_PENDING'
  AND retry_count >= #{retryMax}

mapper.select:
SELECT * FROM rwd_grant_record
WHERE fulfillment_ref = #{fulfillmentRef}
LIMIT 1

mapper.update:
UPDATE rwd_grant_record
SET fulfillment_status = 'FULFILL_FAILED',
    fulfill_fail_reason = 'MANUAL',
    updated_at = #{now}
WHERE id = #{id}
  AND fulfillment_status IN ('SENDING', 'FULFILL_FAILED')

mapper.select:
SELECT * FROM rwd_grant_record
WHERE status = 'CLAIMING'
  AND updated_at < #{cutoff}
ORDER BY updated_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE rwd_grant_record
SET status = 'WON',
    retry_count = retry_count + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'CLAIMING'

mapper.select:
SELECT * FROM rwd_grant_record
WHERE status IN ('WON', 'RETRY_PENDING')
  AND expire_at IS NOT NULL
  AND expire_at <= #{now}
ORDER BY expire_at ASC, id ASC
LIMIT #{limit}

SELECT * FROM rwd_grant_record
WHERE status = 'GRANTED'
  AND fulfillment_status = 'SENDING'
  AND updated_at < #{cutoff}
ORDER BY updated_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE rwd_grant_record
SET recon_status = 'PENDING',
    updated_at = #{now}
WHERE id = #{id}
  AND recon_status = 'NONE'

mapper.select:
SELECT * FROM rwd_grant_record
WHERE category_code = #{categoryCode}
  AND recon_status = 'PENDING'
  AND simulated = 0
  AND fulfillment_status IN ('ARRIVED', 'SENDING', 'FULFILL_FAILED')
  AND granted_at >= #{from}
  AND granted_at < #{to}
ORDER BY id ASC

SELECT * FROM rwd_grant_record
WHERE user_id = #{userId}

  AND (status IN ('WON', 'CLAIMING', 'RETRY_PENDING')
    OR (status = 'GRANTED' AND fulfillment_status IN ('SENDING', 'FULFILL_FAILED')))

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
